SELECT try_divide(CAST(SUM(CASE WHEN installments > 1 THEN 1 ELSE 0 END) AS DOUBLE),COUNT(*)) AS share_installments
FROM `workspace`.`approval_copilot`.`silver_payments`
WHERE country = 'BR' AND NOT is_cross_border AND business_date BETWEEN DATE'2026-07-01' AND DATE'2026-07-31' AND sent_to_acquirer = true;
